/* Interface VoltCalc v3. As grandezas elétricas e seleções vêm da API Python. */
(()=>{
'use strict';
const M=window.VoltModel,DB=window.NBR1997,HELP=window.VoltHelp;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(+v)?(+v).toLocaleString('pt-BR',{maximumFractionDigits:d}):'—';
const STORAGE='voltcalc_guiado_v3',OLD_STORAGE='voltcalc_guiado_v2';
const LABELS=['Circuito','Grandezas','Instalação','Agrupamento','Condições','Resultado'];
const TYPES=[['lighting','Iluminação','Lâmpadas e luminárias','☼'],['sockets','Tomadas','Equipamentos conectados','♧'],['motor','Motor elétrico','Bombas e máquinas','⚙'],['shower','Chuveiro','Aquecimento elétrico','♨'],['transformer','Transformador','Alimentação de cargas','▣'],['other','Outros','Outros equipamentos','⌁']];
const INSTALLATIONS=[['embedded','Eletroduto embutido','Tubulação dentro da parede'],['conduit','Eletroduto aparente','Tubulação sobre a parede'],['surface','Sobre a parede','Cabo fixado diretamente'],['buried','Cabos enterrados no solo','Instalação subterrânea · não é aterramento'],['tray','Bandeja ou leito','Suporte aberto · cálculo pendente'],['overhead','Ao ar livre','Requer enquadramento · cálculo pendente']];
const CONNECTIONS=[['fn','Fase + neutro'],['ff','Fase + fase (duas fases)'],['tri','Trifásico equilibrado']];
let state={projectName:'Meu projeto',circuits:[],draft:M.newCircuit(),editingId:null,selected:null,supply:M.supplyDefaults(),reactance:.08,importInfo:null,page:'wizard',mode:'guided',step:1};
let tableShown='31',toastTimer,modalFocus=null,renderVersion=0,summaryVersion=0,serviceError='';
const cache=new Map(),pending=new Map();
let boardCache=null,boardKey='',csvPreview=null;
const PREVIOUS='voltcalc_before_csv_v3';
async function prepareBoard(){
 const key=JSON.stringify([state.circuits,state.supply]);if(key===boardKey&&boardCache)return true;
 try{const response=await fetch('/api/panel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({circuits:state.circuits,supply:state.supply}),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error);if(key!==JSON.stringify([state.circuits,state.supply]))return false;boardCache=data;boardKey=key;return true;}catch{boardCache=null;boardKey='';serviceError='Não foi possível atualizar o quadro de cargas. Mantenha o servidor Python aberto e tente novamente.';return false;}
}
const resultKey=c=>JSON.stringify([c,state.reactance,state.supply]);
const viewKey=()=>JSON.stringify([state.draft,state.circuits,state.supply,state.reactance,state.page,state.mode,state.step]);
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function persist(){syncTechnical();try{localStorage.setItem(STORAGE,JSON.stringify(M.projectData(state)));return true;}catch{toast('Não foi possível gravar no navegador. Exporte um backup JSON.');return false;}}
function load(){try{const raw=localStorage.getItem(STORAGE)||localStorage.getItem(OLD_STORAGE);if(raw)Object.assign(state,M.readProject(JSON.parse(raw)));}catch(error){toast('Falha ao restaurar: '+error.message+'. O armazenamento anterior foi preservado.');}}
function calc(c){return cache.get(resultKey(c))||{c,ib:null,voltage:null,loaded:null,totals:{},fct:null,fca:null,combinedFactor:null,requiredAmpacity:null,chosen:null,cableCandidate:null,issues:[],notices:[],criteria:{},determining:[],protection:{},segments:[],endpoints:[],pending:true};}
async function prepare(circuits){
 const unique=[...new Map(circuits.map(c=>[resultKey(c),c])).values()];
 const missing=unique.filter(c=>!cache.has(resultKey(c))&&!pending.has(resultKey(c)));
 if(missing.length){
  const snapshots=JSON.parse(JSON.stringify(missing)),reactance=state.reactance,supply=structuredClone(state.supply),keys=snapshots.map(c=>JSON.stringify([c,reactance,supply]));
  const task=(async()=>{try{
   const response=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({circuits:snapshots,reactance,supply}),signal:AbortSignal.timeout(15000)});
   const data=await response.json();if(!response.ok||!Array.isArray(data.results)||data.results.length!==keys.length)throw Error(data.error||'Resposta inválida.');
   data.results.forEach((r,i)=>cache.set(keys[i],r));serviceError='';while(cache.size>1000)cache.delete(cache.keys().next().value);
  }catch(error){serviceError='Servidor indisponível ou dados recusados. Mantenha o Python aberto e tente novamente.';}
  finally{keys.forEach(k=>pending.delete(k));}})();
  keys.forEach(k=>pending.set(k,task));
 }
 await Promise.all(unique.map(c=>pending.get(resultKey(c))).filter(Boolean));
 return unique.every(c=>cache.has(resultKey(c)));
}
function helpButton(key,label='Saiba mais'){return `<button type="button" class="help-btn" data-help="${esc(key)}" aria-label="${esc(label)}">?</button>`;}
function field(label,key,options={}){
 const value=options.value!==undefined?options.value:state.draft[key],scope=options.scope||'field',index=options.index;
 const inputId=`${scope}-${index===undefined?'':index+'-'}${key}${options.suffix||''}`;
 const attrs=`id="${inputId}" data-${scope}="${key}" ${index!==undefined?`data-index="${index}"`:''}`;
 let input=options.options?`<select ${attrs}>${options.options.some(([v])=>String(v)===String(value))?'':'<option value="" selected>Selecione · pendente</option>'}${options.options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:
 `<input ${attrs} type="${options.text?'text':'number'}" value="${esc(value)}" ${options.text?'maxlength="100"':'step="any"'} ${options.min!==undefined?`min="${options.min}"`:''} ${options.max!==undefined?`max="${options.max}"`:''}>`;
 return `<div class="field ${options.className||''}"><div class="field-caption"><label for="${inputId}">${label}</label>${options.help?helpButton(options.help,`Ajuda: ${label}`):''}</div>${input}${options.hint?`<span class="hint">${options.hint}</span>`:''}</div>`;
}
function notice(text,kind=''){return `<div class="notice ${kind}">${text}</div>`;}
function intro(step){const titles=['','Qual circuito você vai dimensionar?','Quais equipamentos serão alimentados?','Como os cabos serão instalados?','Quantos circuitos compartilham o percurso?','Quais são as condições do circuito?','Entenda o dimensionamento'];return `<span class="eyebrow">Passo ${step} de 6</span><h2>${titles[step]} ${helpButton(['','circuit','power','installation','groupCount','distance','result'][step])}</h2>`;}
function stepper(){return `<ol class="stepper">${LABELS.map((text,i)=>`<li class="${state.step===i+1?'current':state.step>i+1?'done':''}"><button data-step="${i+1}" aria-current="${state.step===i+1?'step':'false'}" aria-label="Etapa ${i+1}: ${text}"><span class="step-dot">${i+1}</span><span class="step-name">${text}</span></button></li>`).join('')}</ol>`;}
function circuitView(){return `<p class="step-description">Escolha o uso principal. Na próxima etapa, adicione equipamentos com potências e posições diferentes.</p><div class="choice-grid">${TYPES.map(([key,name,desc,icon])=>`<button data-choose="type" data-value="${key}" class="choice-btn ${state.draft.type===key?'selected':''}" aria-pressed="${state.draft.type===key}"><span class="choice-icon">${icon}</span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="fieldset">${field('Identificação do circuito','number',{text:true,hint:'Opcional. Ex.: 1, C1, IL-01.'})}${field('Nome do circuito','description',{text:true,hint:'Ex.: Iluminação térreo, tomadas da cozinha, motor da bomba.'})}</div>`;}
function supplyView(){const s=state.supply;return `<details class="details supply-details" open><summary>Alimentação da instalação ${helpButton('supply')}</summary><p class="hint">Dados do projeto inteiro. Uma casa trifásica pode ter circuitos fase–neutro e fase–fase.</p><div class="input-grid two">${field('Fases disponíveis na instalação','phases',{scope:'supply',value:s.phases,options:[['mono','Monofásica · fase R (A) + neutro'],['bi','Bifásica · fases R e S (A e B) + neutro'],['tri','Trifásica · fases R, S e T (A, B e C) + neutro']]})}${field('Tensões da rede · fase–neutro / fase–fase','network',{scope:'supply',value:s.network,options:[['127/220','127 / 220 V'],['220/380','220 / 380 V'],['custom','Informar outra rede']]})}${s.network==='custom'?field('Tensão fase–neutro (V)','phaseVoltage',{scope:'supply',value:s.phaseVoltage,min:1})+field('Tensão fase–fase (V)','lineVoltage',{scope:'supply',value:s.lineVoltage,min:1}):''}</div></details>`;}
function connectionView(){const c=state.draft,opts=c.connection==='legacy'?[['legacy','Monofásico importado · confirmar ligação'],...CONNECTIONS]:CONNECTIONS;
 const phases=c.connection==='tri'?[['ABC','R + S + T (A + B + C)']]:c.connection==='ff'?[['AB','R + S (A + B)'],['BC','S + T (B + C)'],['CA','T + R (C + A)']]:[['A','R (A) + neutro'],['B','S (B) + neutro'],['C','T (C) + neutro']];
 return `<div class="fieldset"><div class="field-title">Ligação deste circuito ${helpButton('connection')}</div><div class="input-grid two">${field('Ligação do circuito','connection',{options:opts,help:'connection'})}${field('Fases utilizadas','phaseSet',{options:phases})}${field('Tensão do circuito','voltageMode',{options:[['auto','Usar a tensão da rede'],['manual','Informar tensão manualmente']],help:'supply'})}${c.voltageMode==='manual'||c.connection==='legacy'?field('Tensão aplicada à carga (V)','voltage',{min:1,help:'connection'}):'<div class="field"><label>Tensão calculada pela ligação</label><output class="input-like" data-live-voltage>—</output></div>'}</div><div data-live-link class="explain"></div>${c.connection==='tri'?notice('Cada grupo abaixo deve representar a potência total equilibrada nas três fases. Lâmpadas ligadas a uma fase e neutro devem ser cadastradas em um circuito fase–neutro.','warn'):''}</div>`;
}
function equipmentView(){const c=state.draft;return `${c.source?notice('CSV: esta linha representa a carga agregada do circuito. Quantidade 1 significa um total importado, não um equipamento físico. Substitua por grupos reais e informe as distâncias para calcular a queda.','warn'):''}<div class="card-title equipment-title"><div><h3>Equipamentos do circuito ${helpButton('circuit')}</h3><p>Todos os grupos abaixo pertencem a este único circuito e à mesma proteção. Separe os equipamentos por potência ou posição; isso não cria circuitos adicionais.</p></div><button type="button" class="btn secondary small" data-action="addLoad">+ Adicionar grupo</button></div><div class="equipment-list">${c.loads.map((load,i)=>{
 const f=(label,key,opts={})=>field(label,key,{...opts,scope:'load',index:i,value:load[key]});
 return `<fieldset class="equipment-card"><legend>Grupo de equipamentos ${i+1}</legend><div class="equipment-actions"><button class="btn ghost small" data-remove-load="${i}" ${c.loads.length===1?'disabled':''} aria-label="Remover grupo ${i+1}">Remover</button></div><div class="equipment-fields">${f('Descrição','description',{text:true,className:'wide'})}${f('Quantidade','quantity',{min:1})}${f('Potência por unidade','power',{min:.001,help:'power'})}${f('Unidade','unit',{options:['W','kW','VA','kVA','CV','HP'].map(v=>[v,v])})}${f('Fator de potência','powerFactor',{min:.01,max:1,help:'powerFactor'})}${['CV','HP'].includes(load.unit)?f('Rendimento η','efficiency',{min:.01,max:1,help:'efficiency'}):''}${f('Distância de ida desde o quadro (m)','distance',{min:0,help:'distance',className:'wide',hint:'Todos os equipamentos desta linha estão na mesma posição. Escolha o percurso logo abaixo dos grupos.'})}</div></fieldset>`;
 }).join('')}</div><div data-live-subtotals></div><div data-live-totals class="stats-row live-totals"></div>${notice('O FP inicial 1 é uma hipótese: confirme os dados do equipamento ou driver. Todas as cargas cadastradas são consideradas ligadas simultaneamente.')}`;}
function methodOf(c){if(c.unknownInstallation)return null;if(c.methodOverride)return c.methodOverride;if(c.installation==='embedded'&&c.wall==='thermal')return c.cableForm==='single'?'A1':'A2';if(['embedded','conduit'].includes(c.installation))return c.cableForm==='single'?'B1':'B2';return {surface:'C',buried:'D'}[c.installation]||null;}
function installationView(){const c=state.draft;return `<p class="step-description">O caminho do cabo e os materiais ao redor determinam como o calor se dissipa.</p><div class="picture-grid">${INSTALLATIONS.map(([key,name,desc])=>`<button class="picture-card ${c.installation===key?'selected':''}" data-choose="installation" data-value="${key}" aria-pressed="${c.installation===key}">${window.VoltArt(key)}<strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><div class="fieldset"><div class="input-grid two">${field('Construção do cabo','cableForm',{options:[['single','Condutores isolados / cabos unipolares'],['multi','Cabo multipolar (inclui bipolar)']],help:'cableForm'})}${c.installation==='embedded'?field('Material da parede','wall',{options:[['masonry','Alvenaria convencional'],['thermal','Parede termicamente isolante']],help:'wall'}):''}${field('Material do condutor','metal',{options:[['Cu','Cobre'],['Al','Alumínio']],help:'metal'})}${field('Isolação do cabo','insulation',{options:[['PVC','PVC · 70 °C'],['EPR','EPR · 90 °C'],['XLPE','XLPE · 90 °C']],help:'insulation'})}${['embedded','conduit','buried'].includes(c.installation)?field('Material do eletroduto · registro','conduitType',{options:[['PVC','PVC'],['metal','Metálico'],['other','Outro / confirmar']],help:'conduitType'}):''}</div></div><label class="radio-row"><input type="checkbox" data-field="unknownInstallation" ${c.unknownInstallation?'checked':''}>Não sei identificar a instalação — manter seleção pendente</label><details class="details"><summary>Ver fundamento técnico e método de referência</summary><div class="explain">Método estimado: <strong>${esc(methodOf(c)||'Pendente')}</strong>. Base histórica: tabela 28, NBR 5410:1997. Material do eletroduto é documental, sem fator adicional automático. ${state.mode==='technical'?field('Sobrescrever método','methodOverride',{options:[['','Automático'],...['A1','A2','B1','B2','C','D'].map(x=>[x,x])],help:'installation'}):''}</div></details>${['tray','overhead'].includes(c.installation)?notice('Esta disposição ainda não possui todas as tabelas necessárias no motor. A seção ficará pendente.','warn'):''}`;}
function groupingView(){const c=state.draft;return `<div class="concept-note"><strong>${c.loads.length} grupo(s) de equipamentos neste cadastro = 1 circuito.</strong><p>Conte os circuitos que compartilham a instalação, incluindo este. Exemplo: iluminação do jardim e tomadas no mesmo eletroduto são 2 circuitos. Dois grupos de lâmpadas sob a mesma proteção continuam sendo 1 circuito.</p></div><p class="step-description">Circuitos próximos aquecem uns aos outros. O agrupamento pode reduzir a capacidade de condução dos cabos.</p><div class="choice-grid">${[['bundle','No mesmo eletroduto ou em feixe','Cabos próximos, sem espaçamento relevante.'],['spaced','Separados / espaçados','A disposição e o afastamento precisam ser considerados.'],['unknown','Não sei informar','O fator ficará pendente quando houver vários circuitos.']].map(([key,title,desc])=>`<button data-choose="groupLayout" data-value="${key}" class="choice-btn ${c.groupLayout===key?'selected':''}"><strong>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="fieldset"><div class="input-grid two">${field('Quantos circuitos estão agrupados?','groupCount',{min:1,max:20,help:'groupCount',hint:'Inclua este circuito. Não conte grupos de lâmpadas nem fios. Informe 1 quando não houver outro circuito junto.'})}<div class="field"><label>Fator de agrupamento (FCA)</label><output data-live-group class="input-like">—</output></div></div><div data-live-group-explanation></div></div><details class="details"><summary>Ver fundamento técnico</summary><p class="hint">Fatores da tabela 37, item 1, da base histórica, somente para as disposições implementadas. Agrupamento subterrâneo e espaçamentos especiais exigem outros fatores.</p></details>`;}
function protectionView(){const c=state.draft;return `<div class="fieldset"><div class="field-title">Proteção elétrica ${helpButton('breakerMode')}</div><div class="input-grid two">${field('Como selecionar o disjuntor?','breakerMode',{options:[['auto','Sugerir disjuntor'],['verify','Verificar disjuntor informado']],help:'breakerMode'})}${c.breakerMode==='verify'?field('Corrente nominal informada (A)','breakerCurrent',{min:1,help:'breakerMode',hint:'A seção será procurada considerando este disjuntor.'}):'<p class="hint">O motor procura uma corrente nominal na lista disponível e uma seção compatível com os critérios implementados.</p>'}</div><details class="details" ${state.mode==='technical'?'open':''}><summary>Características do dispositivo e curto-circuito</summary><div class="input-grid two advanced-fields">${field('Curva de atuação · registro','breakerCurve',{options:['B','C','D'].map(x=>[x,x]),help:'breakerCurve'})}${field('Relação I₂/In adotada','i2Factor',{min:1,max:3,help:'i2Factor'})}${field('Corrente de curto-circuito Ik (kA)','shortIk',{min:0,help:'shortIk',hint:'Deixe vazio se não houver estudo.'})}${field('Designação da capacidade','breakingCapacityType',{options:[['Icn','Icn'],['Icu','Icu']],help:'breakerIcu'})}${field(`Capacidade de interrupção ${esc(c.breakingCapacityType)} (kA)`,'breakerIcu',{min:0,help:'breakerIcu',hint:'Valor do dispositivo na tensão aplicável.'})}</div></details></div>`;}
function conditionsView(){const c=state.draft;return `<div class="input-grid two">${field('Temperatura no local dos cabos (°C)','temperature',{min:10,max:80,help:'temperature',hint:methodOf(c)==='D'?'Temperatura do solo.':'Temperatura do ambiente ao redor dos cabos.'})}${field('Limite de queda do circuito (%)','maxDrop',{min:.1,max:20,help:'maxDrop',hint:'4% é o valor inicial configurável; confirme o critério do projeto.'})}<div class="field"><div class="field-caption"><label>Condutores carregados</label>${helpButton('loaded')}</div><output data-live-loaded class="input-like">—</output><span class="hint">Definidos pela ligação do circuito.</span></div></div><div data-live-temperature></div><div class="route-recap"><strong>Distâncias e percurso já cadastrados em Grandezas</strong><div data-live-route>${routePreview()}</div><button class="btn secondary small" data-review-step="2">Editar equipamentos e distâncias →</button></div>${methodOf(c)==='D'?`<details class="details"><summary>Solo · dados documentais ${helpButton('soilResistance')}</summary><div class="input-grid two">${field('Resistividade térmica (K·m/W)','soilResistance',{min:0,help:'soilResistance'})}${field('Profundidade (m)','soilDepth',{min:0,help:'soilResistance'})}</div></details>`:''}${protectionView()}`;}
function stat(title,value){return `<div class="stat"><small>${title}</small><strong>${value}</strong></div>`;}
function check(title,value,ok){return `<div class="check-row"><span>${title}</span><strong class="${ok===true?'text-ok':ok===false?'text-bad':'text-pending'}">${esc(value||'')} ${ok===true?'· Atende neste critério':ok===false?'· Não atende':'· Pendente'}</strong></div>`;}
function traceView(r){if(!r.segments.length)return notice('Os trechos e quedas serão exibidos quando houver dados e seção preliminar disponíveis.');return `<details class="details" open><summary>Queda de tensão por trecho e por equipamento ${helpButton('distance')}</summary><p class="hint">${r.routeMode==='linear'?'Percurso compartilhado em sequência.':'Ramais independentes partindo do quadro.'} Valores para ${fmt((r.chosen||r.cableCandidate)?.section)} mm². Tensão de referência: ${fmt(r.voltage)} V.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Trecho</th><th>Extensão</th><th>Corrente</th><th>Queda no trecho</th><th>Acumulada no caminho</th></tr></thead><tbody>${r.segments.map(s=>`<tr><td>${fmt(s.start)} → ${fmt(s.end)} m</td><td>${fmt(s.length)} m</td><td>${fmt(s.current)} A</td><td>${fmt(s.dv)} V</td><td>${fmt(s.accumulated)} V</td></tr>`).join('')}</tbody></table></div><div class="table-wrap endpoint-table"><table class="data-table"><thead><tr><th>Grupo</th><th>Posição desde o quadro</th><th>Queda estimada</th></tr></thead><tbody>${r.endpoints.map(e=>`<tr><td>${esc(e.description)}</td><td>${fmt(e.distance)} m</td><td>${fmt(e.dvPct)}%</td></tr>`).join('')}</tbody></table></div><p class="hint">Queda anterior ao quadro, harmônicas e desequilíbrio não estão incluídos.</p></details>`;}
function correctionCard(kind,r,compact=false){const info=r.corrections?.[kind];if(!info)return '';return `<div class="factor-card ${info.factor==null?'factor-missing':''}"><div><span>${kind==='temperature'?'Temperatura · FCT':'Agrupamento · FCA'}</span><strong>${info.factor==null?'Não disponível':fmt(info.factor)}</strong></div><p>${esc(compact&&kind==='grouping'&&info.factor==null?'Fator indisponível para a condição cadastrada. O bloqueio acima explica o motivo e como revisar.':info.message)}</p>${info.reference?`<small>${esc(info.reference)}</small>`:''}</div>`;}
function selectionReadiness(r,compact=false){
 if(r.pending)return '';
 const blockers=r.selectionBlockers||[],checks=(r.diagnostics||[]).filter(d=>!d.blocksSelection);
 if(compact&&blockers.length)return `<div class="preflight-note"><strong>${blockers.length} ${blockers.length===1?'bloqueio impede':'bloqueios impedem'} concluir a seleção</strong><p>Você pode continuar o cadastro, mas o cabo e o disjuntor automático dependem destes pontos:</p><div class="grid-tabs">${[...new Set(blockers.map(d=>d.step))].map(step=>`<button class="btn secondary small" data-review-step="${step}">Revisar ${LABELS[step-1].toLowerCase()} →</button>`).join('')}</div></div>`;
 const list=entries=>`<ul class="resolution-list">${entries.map(d=>`<li><p>${esc(d.message)}</p><button class="btn secondary small" data-diagnostic="${r.diagnostics.findIndex(x=>x.field===d.field&&x.scope===d.scope&&x.index===d.index&&x.message===d.message)}">Revisar ${LABELS[d.step-1].toLowerCase()} →</button></li>`).join('')}</ul>`;
 return `${blockers.length?`<section class="resolution-box" aria-label="O que impede o dimensionamento"><span class="eyebrow">${blockers.length} ${blockers.length===1?'bloqueio identificado':'bloqueios identificados'}</span><h3>${r.ib!=null?'A corrente foi calculada. Falta concluir a seleção do cabo e do disjuntor.':'Precisamos conferir os dados da carga.'}</h3>${list(blockers)}<p class="hint">Sem uma seção definida, a queda final também não pode ser apresentada. Revise os dados conforme a instalação real; limitações de tabela são limitações do programa.</p></section>`:`<div class="notice readiness-ok">Dados suficientes para a seleção preliminar de cabo e disjuntor. As verificações complementares continuam separadas abaixo.</div>`}${checks.length?`<details class="details additional-checks"><summary>${checks.length} ${checks.length===1?'verificação complementar · não impede':'verificações complementares · não impedem'} a seleção nominal</summary>${list(checks)}</details>`:''}`;
}
function corrections(r){return `<div class="explain"><strong>Capacidade tabelada necessária do cabo</strong> ${helpButton('capacity')}<p>Este valor se refere ao cabo, não à corrente nominal do disjuntor. A corrente da carga ${r.ib==null?'ainda depende dos dados dos equipamentos':`é ${fmt(r.ib)} A`}.</p><div class="factor-grid">${correctionCard('temperature',r)}${correctionCard('grouping',r,true)}</div>${r.requiredAmpacity!=null?`<div class="equation">${fmt(r.ib)} A ÷ (${fmt(r.fct)} × ${fmt(r.fca)}) = <b>${fmt(r.requiredAmpacity)} A</b></div><p>Essa é a capacidade que procuramos na tabela antes das correções.${r.chosen?` Para o cabo de ${fmt(r.chosen.section)} mm²: ${fmt(r.chosen.itab)} A × ${fmt(r.fct)} × ${fmt(r.fca)} = <b>${fmt(r.chosen.iz)} A</b> de capacidade corrigida.`:''}</p>`:`<p class="factor-dependency">${r.ib==null?'Precisamos da corrente da carga':r.fct==null&&r.fca==null?'Precisamos dos fatores de temperatura e de agrupamento':r.fct==null?'Falta o fator de temperatura':'Falta o fator de agrupamento'} para obter a capacidade tabelada necessária. O motivo está indicado acima.</p>`}<small>Os fatores corrigem a capacidade do cabo; não aumentam a corrente consumida pela carga.</small></div>`;}
function routePreview(){const c=state.draft,loads=[...c.loads].sort((a,b)=>Number(a.distance)-Number(b.distance));return `<div class="route-preview"><strong>Quadro · proteção deste circuito</strong><div class="route-path ${c.routeMode==='independent'?'route-branches':''}">${loads.map(l=>`<span>→ ${esc(l.description||'Equipamento')} <b>${fmt(l.distance)} m</b> desde o quadro</span>`).join('')}</div><p>${c.routeMode==='linear'?'Um caminho compartilhado: a corrente diminui após as derivações para as cargas.':'Um caminho de cabos separado por grupo, partindo da mesma proteção. Se houver um tronco comum antes da separação, este modelo não representa o percurso.'}</p></div>`;}
function routeView(){return `<div class="fieldset"><div class="field-title">Percurso dentro deste circuito ${helpButton('distance')}</div>${field('Como os grupos de equipamentos são atendidos?','routeMode',{options:[['linear','Caminho compartilhado, com cargas ao longo dele'],['independent','Caminhos separados desde a proteção no quadro']],help:'distance'})}<div data-live-route>${routePreview()}</div><p class="hint">Percurso descreve por onde a corrente chega às cargas. Agrupamento descreve o aquecimento entre circuitos próximos: cabos de caminhos diferentes podem estar no mesmo eletroduto. O modelo usa uma seção e as mesmas condições térmicas em todos os caminhos.</p></div>`;}

function resultView(){const r=calc(state.draft),b=r.chosen,p=r.protection;
 if(r.pending)return notice(serviceError||'Calculando no servidor Python…',serviceError?'bad':'');
 if(!b)return `<div class="stats-row result-stats">${stat('Corrente da carga · Ib',r.ib!=null?fmt(r.ib)+' A':'Confira os dados da carga')}${stat('Potência ativa dos grupos',r.loadResults?.length===state.draft.loads.length?fmt(r.totals.p)+' W':'Cadastro incompleto')}${p.nominal!=null?stat('Disjuntor informado · ainda não aprovado',fmt(p.nominal)+' A'):''}</div>${selectionReadiness(r)}${corrections(r)}${r.cableCandidate?notice('Existe uma seção candidata para corrente e queda, mas a coordenação com a proteção ainda não foi atendida.','warn'):''}<button class="btn secondary" data-action="saveDraft">Salvar rascunho para continuar depois</button>`;
 return `${selectionReadiness(r)}${r.issues.map(text=>notice(esc(text),'bad')).join('')}<div class="stats-row result-stats">${stat('Corrente da carga · Ib',fmt(r.ib)+' A')}${stat('Capacidade tabelada necessária do cabo',fmt(r.requiredAmpacity)+' A')}${stat('Seção preliminar',b?fmt(b.section)+' mm²':'Pendente')}</div><div class="overview-grid"><div class="key-metric"><small>${state.draft.breakerMode==='verify'?'Disjuntor informado':'Disjuntor nominal sugerido'}</small><strong>${fmt(p.nominal)} A</strong></div><div class="key-metric"><small>Maior queda estimada</small><strong>${b?fmt(b.dvPct)+'%':'Pendente'}</strong></div></div>${p.failed?notice('Há uma incompatibilidade na proteção informada. Consulte as verificações abaixo.','bad'):''}${corrections(r)}<h3 class="small-heading result-heading">O que determinou a seção?</h3><div class="criteria-grid">${Object.entries({minimum:'Seção mínima do modelo',ampacity:'Capacidade de corrente',voltageDrop:'Queda de tensão',protection:'Coordenação com o disjuntor'}).map(([key,label])=>`<div><span>${label}</span><strong>${fmt(r.criteria[key])} mm²</strong></div>`).join('')}</div><p class="hint">${b?'Critério(s) determinante(s): '+esc(r.determining.join('; '))+'.':'Não foi possível combinar todos os critérios. Corrija os erros ou consulte as pendências.'}</p><div class="checks">${check('Corrente da carga ≤ nominal do disjuntor',`${fmt(r.ib)} A ≤ ${fmt(p.nominal)} A`,p.loadOk)}${check('Nominal do disjuntor ≤ capacidade corrigida',`${fmt(p.nominal)} A ≤ ${fmt((b||r.cableCandidate)?.iz)} A`,p.cableOk)}${check('Atuação convencional I₂ ≤ 1,45 × Iz','Hipótese I₂/In: '+fmt(state.draft.i2Factor),p.conventionalOk)}${check(`Ik ≤ ${esc(state.draft.breakingCapacityType)}`,'Comparação isolada em kA',p.shortOk)}${check('Curva real, partida, curto térmico e seletividade','',null)}</div>${traceView(r)}<details class="details"><summary>Hipóteses, referências e verificações pendentes</summary>${r.notices.map(text=>notice(esc(text),'warn')).join('')}<p class="hint">Base histórica NBR 5410:1997. Método ${esc(r.method||'pendente')}, tabela ${r.table}, fatores de temperatura e agrupamento. Neutro, PE, DR/DPS e seccionamento não são dimensionados.</p></details><div class="result-alert">Resultado preliminar. As verificações parciais não representam aprovação do projeto.</div><button class="btn primary" data-action="saveCircuit">${state.editingId?'Atualizar circuito':'Salvar circuito no projeto'}</button>`;
}
function stepView(step){return intro(step)+[null,circuitView,()=>supplyView()+connectionView()+equipmentView()+routeView(),installationView,groupingView,conditionsView,resultView][step]();}
function wizardView(){return `<section class="panel wizard">${stepper()}<div class="step-body">${stepView(state.step)}</div>${state.draft.source&&state.step<6?'<p class="hint">Circuito importado: você pode salvar o cadastro ainda incompleto. Os cálculos que dependem dos dados ausentes continuarão pendentes.</p><button class="btn secondary small" data-action="saveCircuit">Salvar cadastro pendente</button>':''}${state.step<6?'<div data-live-readiness></div>':''}<div class="helper-row"><span class="info-line">Os pontos de interrogação explicam cada escolha e seus efeitos.</span><div class="nav-buttons">${state.step>1?'<button class="btn secondary" data-action="back">‹ Voltar</button>':''}${state.step<6?'<button class="btn primary" data-action="next">Próximo passo →</button>':''}</div></div></section>`;}
function summaryView(){const c=state.draft,raw=calc(c),r={...raw,totals:raw.loadResults?.length===c.loads.length?raw.totals:{}},b=r.chosen;const show=state.step===6||state.mode==='technical'||state.page!=='wizard';return `<section class="panel preview-top"><h2 class="summary-title">Resumo do circuito</h2>${[['Circuito',c.description||'Sem nome'],['Grupos / equipamentos',`${c.loads.length} / ${fmt(r.totals.quantity,0)}`],['Potência ativa',fmt(r.totals.p)+' W'],['Potência aparente',fmt(r.totals.s)+' VA'],['Ligação',CONNECTIONS.find(x=>x[0]===c.connection)?.[1]||'A confirmar'],['Tensão',fmt(r.voltage)+' V'],['Corrente da carga',fmt(r.ib)+' A']].map(([label,value])=>`<div class="summary-item"><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</section><section class="panel preview-result"><h2 class="summary-title">Resultado preliminar ${helpButton('result')}</h2>${show&&!b&&!r.pending?`<p>${(r.selectionBlockers||[]).length} bloqueio(s) impedem a seleção. Os motivos e os botões para revisão aparecem no resultado.</p>`:show?`${r.protection.failed?notice('Proteção informada incompatível.','bad'):''}<div class="result-mini"><div><span>Cabo preliminar</span><strong>${b?fmt(b.section)+' mm²':'Pendente'}</strong></div></div><div class="result-mini"><div><span>${c.breakerMode==='verify'?'Disjuntor informado':'Disjuntor sugerido'}</span><strong>${fmt(r.protection.nominal)} A</strong></div></div><div class="result-mini"><div><span>Maior queda estimada</span><strong>${b?fmt(b.dvPct)+'%':'Pendente'}</strong></div></div>`:'<p>O resultado será explicado na última etapa. A corrente já acompanha as alterações das cargas.</p>'}<p class="result-note">${r.pending?'Aguardando cálculo…':'Pré-dimensionamento parcial; consulte as condições e pendências.'}</p></section>`;}
function savedResults(){return state.circuits.map((c,i)=>({c,i,r:calc(c)}));}
function loadsView(){return `<section class="panel card-section"><div class="card-title"><div><h2>Quadro de cargas ${helpButton('panelTotals')}</h2><p>Projeto: ${esc(state.projectName)} · rede ${esc(state.supply.network)} V · ${state.circuits.length} circuito(s).</p></div><div class="head-actions"><button class="btn secondary small" data-action="csvDialog">Importar CSV</button><button class="btn secondary small" data-action="example">Exemplo de 8 circuitos</button><button class="btn secondary small" data-action="export">Backup JSON</button><button class="btn primary small" data-action="new">+ Novo circuito</button></div></div><p class="hint">Fases R/S/T correspondem a A/B/C. Os totais utilizam os circuitos salvos; salve as alterações do editor para atualizar o quadro.</p>${window.VoltBoard.render(boardCache,state.circuits,savedResults().map(x=>x.r),state.importInfo)}${localStorage.getItem(PREVIOUS)?'<button class="btn secondary small restore-project" data-action="restorePrevious">Restaurar projeto anterior à importação</button>':''}</section>`;}
function referenceView(){const c=state.draft,method=methodOf(c)||'B1',table=String(tableShown);let headers,rows;if(table==='31'||table==='32'){const columns=DB.meta.columns,ins=table==='31'?'PVC':'EPR_XLPE';headers=['Seção (mm²)',method+' / 2 carregados',method+' / 3 carregados'];rows=Object.entries(DB.ampacities[ins][c.metal]||{}).map(([s,a])=>[s,a[columns.indexOf(method+'/2')],a[columns.indexOf(method+'/3')]]);}else if(table==='35'){headers=['Temperatura (°C)','PVC','EPR/XLPE'];const t=DB.temperature[method==='D'?'soil':'air'];rows=Object.keys(t.EPR_XLPE).map(k=>[k,t.PVC[k],t.EPR_XLPE[k]]);}else {headers=['Circuitos','Fator de agrupamento'];rows=Object.entries(DB.group1);}return `<section class="panel card-section"><h2>Tabela ${esc(table)} · referência histórica</h2>${table==='28'?notice('A1/A2: parede termicamente isolante. B1/B2: conduto em condições aplicáveis. C: cabo diretamente na parede. D: condição enterrada. Confirme as condições completas na norma.'):`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}${notice('Dados parciais da base histórica NBR 5410:1997. Não substituem a publicação e suas notas.','warn')}</section>`;}
function overviewView(){const r=calc(state.draft);return `<section class="panel card-section"><h2>${{sizing:'Dimensionamento explicado',protection:'Verificação de proteção',voltage:'Queda de tensão por percurso'}[state.page]}</h2><p class="sub">Circuito no editor: ${esc(state.draft.description||'Sem nome')}.</p>${state.page==='voltage'?routeView()+'<div id="dependentResult">'+traceView(r)+'</div>':state.page==='protection'?protectionView()+'<div id="dependentResult">'+resultView()+'</div>':resultView()}</section>`;}
function paintLive(){paintDiagnostics();const live=calc(state.draft);document.querySelectorAll('[data-live-temperature]').forEach(el=>el.innerHTML=correctionCard('temperature',live));document.querySelectorAll('[data-live-group-explanation]').forEach(el=>el.innerHTML=live.corrections?`<div class="${live.fca==null?'notice warn':'explain'}">${esc(live.corrections.grouping.message)}</div>`:'');document.querySelectorAll('[data-live-route]').forEach(el=>el.innerHTML=routePreview());document.querySelectorAll('[data-live-readiness]').forEach(el=>el.innerHTML=selectionReadiness(live,true));const raw=calc(state.draft),r={...raw,totals:raw.loadResults?.length===state.draft.loads.length?raw.totals:{}};document.querySelectorAll('[data-live-subtotals]').forEach(el=>el.innerHTML=(r.loadResults||[]).map(l=>`<div class="summary-item"><span>Grupo ${l.index+1} · ${esc(l.description)}</span><strong>${fmt(l.p)} W · ${fmt(l.s)} VA</strong></div>`).join(''));$('summaryPanel').innerHTML=summaryView();document.querySelectorAll('[data-live-totals]').forEach(el=>el.innerHTML=stat('Equipamentos',fmt(r.totals.quantity,0))+stat('Potência ativa',fmt(r.totals.p)+' W')+stat('Corrente calculada',fmt(r.ib)+' A'));document.querySelectorAll('[data-live-voltage]').forEach(el=>el.textContent=fmt(r.voltage)+' V');document.querySelectorAll('[data-live-loaded]').forEach(el=>el.textContent=fmt(r.loaded,0)+' condutores');document.querySelectorAll('[data-live-group]').forEach(el=>el.textContent=r.fca==null?'Não disponível para esta condição':fmt(r.fca));document.querySelectorAll('[data-live-link]').forEach(el=>el.textContent=`Este circuito: ${CONNECTIONS.find(x=>x[0]===state.draft.connection)?.[1]||'ligação a confirmar'}, ${fmt(r.voltage)} V; ${fmt(r.loaded,0)} condutores carregados. ${r.phase==='tri'?'A corrente exibida é por fase.':'A alimentação geral pode ter mais fases que este circuito utiliza.'}`);const status=$('connectionStatus');status.hidden=!serviceError;status.innerHTML=serviceError?`${esc(serviceError)} <button class="btn small" data-action="retry">Tentar novamente</button>`:'';document.querySelectorAll('[data-live-errors]').forEach(el=>el.innerHTML=r.issues.map(text=>notice(esc(text),'bad')).join(''));}
async function refreshSummary(){paintLive();const version=++summaryVersion,key=resultKey(state.draft);await prepare([state.draft]);if(version===summaryVersion&&key===resultKey(state.draft)){paintLive();if(state.page==='protection'||state.page==='voltage'){const area=$('dependentResult');if(area)area.innerHTML=state.page==='voltage'?traceView(calc(state.draft)):resultView();}}}
async function render(){const version=++renderVersion,snapshot=viewKey();await prepare(state.page==='loads'||state.mode==='technical'?[state.draft,...state.circuits]:[state.draft]);if(state.page==='loads')await prepareBoard();if(version!==renderVersion||snapshot!==viewKey())return;
 document.querySelector('.page-layout').classList.toggle('board-layout',state.page==='loads'||state.mode==='technical');$('summaryPanel').hidden=state.page==='loads'||state.mode==='technical';document.querySelector('.mode-toggle').hidden=state.page==='loads';
 $('projectName').value=state.projectName;$('guidedMode').classList.toggle('active',state.mode==='guided');$('technicalMode').classList.toggle('active',state.mode==='technical');$('guidedMode').setAttribute('aria-pressed',state.mode==='guided');$('technicalMode').setAttribute('aria-pressed',state.mode==='technical');
 $('pageTitle').textContent=state.page==='loads'?'Quadro de cargas':state.page==='wizard'?'Dimensionamento de circuitos':'Análise do circuito';$('pageSubtitle').textContent='Cadastre as cargas, entenda os critérios e confira cada resultado.';
 document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===state.page));
 $('mainPanel').innerHTML=state.page==='wizard'?(state.mode==='guided'?wizardView():technicalView()):state.page==='loads'?loadsView():state.page==='reference'?referenceView():overviewView();
 if(state.page==='wizard'&&state.mode==='technical'&&gridDetails!==6)$('mainPanel').insertAdjacentHTML('beforeend','<div data-diagnostics aria-live="polite"></div>');paintLive();
}
function stepError(step){const c=state.draft;const valid=v=>v!==''&&v!==null&&Number.isFinite(+v);if(step===1&&!c.description.trim())return 'Dê um nome ao circuito.';if(step===2){if(!c.loads.every(l=>l.description.trim()&&valid(l.quantity)&&+l.quantity>=1&&Number.isInteger(+l.quantity)&&valid(l.power)&&+l.power>0&&valid(l.powerFactor)&&+l.powerFactor>0&&+l.powerFactor<=1&&(!['CV','HP'].includes(l.unit)||(valid(l.efficiency)&&+l.efficiency>0&&+l.efficiency<=1))))return 'Confira quantidade, potência, fator de potência e rendimento dos grupos.';}if(step===4&&(!valid(c.groupCount)||!Number.isInteger(+c.groupCount)||+c.groupCount<1||+c.groupCount>20))return 'Informe de 1 a 20 circuitos agrupados.';if(step===5&&(!c.loads.every(l=>valid(l.distance)&&+l.distance>=0)||!valid(c.maxDrop)||+c.maxDrop<=0))return 'Confira as distâncias e o limite de queda.';return '';}
async function goStep(next){await prepare([state.draft]);if(next>state.step){for(let s=state.step;s<next;s++){const entry=(calc(state.draft).diagnostics||[]).find(d=>d.step===s&&d.blocking);const error=entry?.message||stepError(s);if(error){state.step=s;await render();toast(error);return;}}}state.step=next;persist();render();window.scrollTo({top:0,behavior:'smooth'});}
function changeCircuit(key,value){const c=state.draft;if(!Object.hasOwn(c,key))return;c[key]=value;if(key==='connection'){c.legacyLoaded=null;c.phaseSet=value==='tri'?'ABC':value==='ff'?'AB':'A';if(value==='legacy')c.voltageMode='manual';}if(key==='installation'){c.methodOverride='';c.unknownInstallation=false;}if(key==='methodOverride'&&value)c.unknownInstallation=false;persist();}
async function saveCircuit(){if(!state.draft.description.trim())return toast('Dê um nome ao circuito.');for(let s=1;s<=5&&!state.draft.source;s++){const error=stepError(s);if(error){state.mode='guided';state.page='wizard';state.step=s;render();toast(error);return;}}
 const key=resultKey(state.draft);if(!await prepare([state.draft])){toast(serviceError);return;}if(key!==resultKey(state.draft)){toast('Os dados mudaram. Salve novamente.');return;}if(calc(state.draft).issues.length&&!state.draft.source){state.page='wizard';state.mode='guided';state.step=6;render();toast('Corrija os campos inválidos apresentados no resultado.');return;}
 const c=M.cleanCircuit(state.draft);if(state.editingId){const index=state.circuits.findIndex(x=>x.id===state.editingId);if(index<0){toast('Circuito original não encontrado.');return;}c.id=state.editingId;state.circuits[index]=c;}else{if(state.circuits.length>=300){toast('Limite de 300 circuitos.');return;}c.id=M.id();state.circuits.push(c);}state.editingId=c.id;state.selected=c.id;state.draft=M.cleanCircuit(c);if(persist())toast('Circuito salvo no projeto.');state.page='loads';render();}
function editCircuit(id){const c=state.circuits.find(c=>c.id===id);if(!c)return;state.draft=M.cleanCircuit(c);state.editingId=id;state.selected=id;state.page='wizard';state.step=1;persist();render();}
function modal(title,body,buttons='<button class="btn secondary" data-close>Fechar</button>'){modalFocus=document.activeElement;$('modalRoot').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}<div class="modal-foot">${buttons}</div></div>`;$('modalRoot').hidden=false;$('modalRoot').querySelector('input,button,select,a')?.focus();}
function closeModal(){$('modalRoot').hidden=true;$('modalRoot').innerHTML='';modalFocus?.focus();}
function csvDialog(){csvPreview=null;modal('Importar quadro de cargas CSV',`<p>Use um CSV separado por ponto e vírgula, com as colunas do exemplo. A linha TOTAL deve informar a rede trifásica 127/220 ou 220/380 V.</p><label for="csvFile">Selecionar arquivo CSV</label><input id="csvFile" type="file" accept=".csv,text/csv"><p class="hint">W e VA serão preservados e usados para obter o FP. Distâncias e condições de instalação ficarão pendentes. Arquivos Excel .xlsx ainda não são importados diretamente.</p>`);}
async function previewCsv(file=null){
 try{
  if(file&&file.size>2e6)throw Error('Limite de 2 MB.');
  let response;if(file){const bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1252').decode(bytes);response=await fetch('/api/import-csv',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,filename:file.name}),signal:AbortSignal.timeout(15000)});}else response=await fetch('/api/example',{signal:AbortSignal.timeout(15000)});
  const data=await response.json();if(!response.ok)throw Error(data.error||'Arquivo recusado.');
  csvPreview=M.readProject(data.project,true);
  modal('Prévia do quadro importado',`<p><strong>${csvPreview.circuits.length} circuitos · rede ${esc(csvPreview.supply.network)} V · ${fmt(data.panel.p)} W</strong></p><p>${data.panel.phases.map(p=>`Fase ${p.label}: ${fmt(p.current)} A`).join(' · ')}</p><ul>${csvPreview.circuits.map(c=>`<li>${esc(c.number)} · ${esc(c.description)}</li>`).join('')}</ul>${data.warnings.map(w=>notice(esc(w),'warn')).join('')}<p>As correntes serão recalculadas. Os disjuntores são valores informados, e o dimensionamento ficará pendente até você preencher os dados ausentes.</p><p>Ao abrir, o projeto atual será guardado neste navegador para restauração. Exporte um backup JSON se quiser manter uma cópia permanente.</p>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" data-action="applyCsv">Abrir como novo projeto</button>`);
 }catch(error){csvPreview=null;toast('Importação recusada: '+error.message);}
}
function applyCsv(){if(!csvPreview)return;try{localStorage.setItem(PREVIOUS,JSON.stringify(M.projectData(state)));localStorage.setItem(STORAGE,JSON.stringify(M.projectData(csvPreview)));}catch{toast('Não foi possível preservar o projeto anterior. Exporte um backup e libere espaço no navegador.');return;}Object.assign(state,csvPreview);csvPreview=null;boardCache=null;closeModal();state.page='loads';render();toast('Quadro importado. Complete os dados pendentes em Editar.');}
function restorePrevious(){try{const raw=localStorage.getItem(PREVIOUS);if(!raw)return;const restored=M.readProject(JSON.parse(raw),true);const current=JSON.stringify(M.projectData(state));localStorage.setItem(STORAGE,JSON.stringify(M.projectData(restored)));localStorage.setItem(PREVIOUS,current);Object.assign(state,restored);boardCache=null;state.page='loads';render();toast('Projeto anterior restaurado. O outro quadro permanece disponível para restauração.');}catch(error){toast('Não foi possível restaurar: '+error.message);}}
function showHelp(key){const help=HELP[key]||HELP.result;modal(help.title,help.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')+(help.source?`<p><a href="${esc(help.source)}" target="_blank" rel="noopener noreferrer">Consultar fundamento técnico</a></p>`:''));}
function settings(){modal('Configurações e backups',`<p>Projetos ficam neste navegador. O backup inclui equipamentos, distâncias, alimentação, rascunho e configurações de cálculo.</p><div class="field"><label for="reactanceInput">Reatância estimada (Ω/km)</label><input id="reactanceInput" type="number" min="0" max="2" step=".01" value="${esc(state.reactance)}"></div><p class="hint">Estimativa comum a todos os trechos. Dados de fabricantes ainda não foram integrados.</p><div class="field-row"><button class="btn secondary" data-action="export">Exportar backup JSON</button><button class="btn secondary" data-action="import">Importar backup JSON</button><input id="importFile" type="file" accept=".json,application/json" hidden></div>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" data-action="saveSettings">Salvar configurações</button>`);}
function exportJson(){const raw=JSON.stringify(M.projectData(state),null,2),href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download='VoltCalc_'+state.projectName.replace(/[^a-z0-9_-]/gi,'_').slice(0,45)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Backup exportado.');}
async function importJson(file){if(!file)return;try{if(file.size>4e6)throw Error('Limite de 4 MB.');const data=M.readProject(JSON.parse(await file.text()),true);if(!confirm(`Importar o projeto com ${data.circuits.length} circuitos e substituir o atual?`))return;Object.assign(state,data);persist();closeModal();state.page='loads';render();toast('Projeto importado.');}catch(error){toast('Importação recusada: '+error.message);}}
async function report(){const snapshot=viewKey();if(!await prepare(state.circuits)||!await prepareBoard()){toast(serviceError);return;}if(snapshot!==viewKey()){toast('Os dados mudaram. Exporte novamente.');return;}const saved=state.draft;$('printArea').innerHTML=`<h1>VoltCalc — Memorial preliminar</h1><p>Projeto: ${esc(state.projectName)} · ${new Date().toLocaleDateString('pt-BR')}<br>Base histórica NBR 5410:1997 · motor Python v3<br>Alimentação: ${esc(state.supply.phases)}, rede ${esc(state.supply.network)}. Reatância: ${fmt(state.reactance,3)} Ω/km.</p><p class="report-warning">Verificações parciais. Este relatório não atesta conformidade integral.</p>${window.VoltBoard.render(boardCache,state.circuits,savedResults().map(x=>x.r),state.importInfo,false)}${savedResults().map(({c,r},i)=>{state.draft=c;return `<section class="report-circuit"><h2>${i+1}. ${esc(c.description)}</h2><p>Ligação: ${esc(c.connection)} · fases ${esc(c.phaseSet)} · ${fmt(r.voltage)} V · ${fmt(r.loaded,0)} carregados.<br>${esc(c.metal)} / ${esc(c.insulation)} · método ${esc(r.method)} · ${fmt(c.temperature)} °C · ${fmt(c.groupCount,0)} circuito(s) agrupado(s) · limite ${fmt(c.maxDrop)}%.</p><table><thead><tr><th>Grupo</th><th>Qtd.</th><th>Potência unitária</th><th>FP</th><th>Distância de ida</th></tr></thead><tbody>${c.loads.map(l=>`<tr><td>${esc(l.description)}</td><td>${fmt(l.quantity,0)}</td><td>${fmt(l.power)} ${esc(l.unit)}</td><td>${fmt(l.powerFactor)}</td><td>${fmt(l.distance)} m</td></tr>`).join('')}</tbody></table>${resultView()}</section>`;}).join('')||'<p>Nenhum circuito salvo. Salve os circuitos antes de emitir o memorial.</p>'}`;state.draft=saved;$('printArea').querySelectorAll('details').forEach(d=>d.open=true);window.print();}
function clickHandler(ev){const btn=ev.target.closest('button');if(!btn)return;const d=btn.dataset;if(d.gridTab||d.gridAction||d.gridDetail!==undefined||d.gridOpen!==undefined||d.diagnostic!==undefined){gridClick(d);return;}if(d.reviewStep){state.page='wizard';if(state.mode==='technical')gridDetails=+d.reviewStep;else state.step=+d.reviewStep;render();return;}if(d.help){ev.preventDefault();showHelp(d.help);return;}if(d.close!==undefined){closeModal();return;}if(d.step){goStep(+d.step);return;}if(d.choose){changeCircuit(d.choose,d.value);render();return;}if(d.page){state.page=d.page;render();return;}if(d.table){tableShown=d.table;state.page='reference';render();return;}if(d.edit){editCircuit(d.edit);return;}if(d.duplicate){if(state.circuits.length>=300)return toast('Limite atingido.');const c=M.cleanCircuit(state.circuits.find(c=>c.id===d.duplicate));c.id=M.id();c.number='';c.description=(c.description+' — cópia').slice(0,70);state.circuits.push(c);persist();render();return;}if(d.delete){const c=state.circuits.find(c=>c.id===d.delete);if(c&&confirm(`Excluir "${c.description}"?`)){state.circuits=state.circuits.filter(x=>x.id!==c.id);if(state.editingId===c.id){state.editingId=null;state.draft=M.newCircuit();}persist();render();}return;}if(d.removeLoad!==undefined){state.draft.loads.splice(+d.removeLoad,1);persist();render();return;}
 const action=d.action||btn.id;switch(action){case 'csvDialog':csvDialog();break;case 'example':previewCsv();break;case 'applyCsv':applyCsv();break;case 'restorePrevious':restorePrevious();break;case 'next':goStep(Math.min(6,state.step+1));break;case 'back':goStep(Math.max(1,state.step-1));break;case 'guidedMode':syncTechnical();state.mode='guided';state.page='wizard';render();break;case 'technicalMode':enterTechnical();break;case 'addLoad':if(state.draft.loads.length>=100)return toast('Limite de 100 grupos por circuito.');state.draft.loads.push(M.newLoad());persist();render();break;case 'new':if(state.mode==='technical'){state.page='wizard';gridClick({gridAction:'add'});break;}state.draft=M.newCircuit();state.editingId=null;state.step=1;state.page='wizard';persist();render();break;case 'saveDraft':if(persist())toast('Rascunho salvo neste navegador, incluindo os dados ainda pendentes.');break;case 'saveCircuit':saveCircuit();break;case 'seeResult':state.mode='guided';state.page='wizard';state.step=6;render();break;case 'saveBtn':state.projectName=$('projectName').value||'Meu projeto';if(persist())toast('Projeto salvo neste navegador.');break;case 'settingsBtn':case 'sidebarSettings':settings();break;case 'printBtn':case 'sidebarReport':report();break;case 'export':exportJson();break;case 'import':$('importFile').click();break;case 'saveSettings':{const value=$('reactanceInput').value;if(value===''||!Number.isFinite(+value)||+value<0||+value>2)return toast('Informe reatância entre 0 e 2 Ω/km.');state.reactance=+value;persist();closeModal();render();break;}case 'retry':render();break;}}
function updateInput(ev){const target=ev.target,d=target.dataset,value=target.type==='checkbox'?target.checked:target.value;if(d.gridRow!==undefined){gridInput(target);return;}if(d.gridSelect!==undefined){if(target.checked)gridSelection.add(d.gridSelect);else gridSelection.delete(d.gridSelect);return;}if(d.gridAll!==undefined){gridSelection=target.checked?new Set(state.circuits.map(c=>c.id)):new Set();render();return;}if(d.bulkKey!==undefined)return;if(target.id==='projectName'){state.projectName=value.slice(0,60);persist();return;}if(d.field)changeCircuit(d.field,value);else if(d.supply){state.supply[d.supply]=value;persist();}else if(d.load){const load=state.draft.loads[+d.index];if(load&&Object.hasOwn(load,d.load)){load[d.load]=value;document.querySelectorAll('[data-load]').forEach(el=>{if(el!==target&&el.dataset.load===d.load&&el.dataset.index===d.index)el.value=value;});if(d.load==='description'){const label=document.querySelector('label[for="load-'+d.index+'-distance-route"]');if(label)label.textContent=(+d.index+1)+'. '+value+' · distância (m)';}persist();}}else return;
 if(target.tagName==='SELECT'||target.type==='checkbox')render();else {refreshSummary();if(state.mode==='technical')refreshGrid();}}
document.addEventListener('click',clickHandler);document.addEventListener('input',ev=>{if(ev.target.tagName!=='SELECT'&&ev.target.type!=='checkbox')updateInput(ev);});document.addEventListener('change',ev=>{if(ev.target.id==='csvFile')previewCsv(ev.target.files[0]);else if(ev.target.id==='importFile')importJson(ev.target.files[0]);else if(ev.target.tagName==='SELECT'||ev.target.type==='checkbox')updateInput(ev);});
document.addEventListener('keydown',ev=>{if($('modalRoot').hidden)return;if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){const nodes=[...$('modalRoot').querySelectorAll('button,input:not([hidden]),select,a')].filter(el=>!el.disabled);if(ev.shiftKey&&document.activeElement===nodes[0]){ev.preventDefault();nodes.at(-1)?.focus();}else if(!ev.shiftKey&&document.activeElement===nodes.at(-1)){ev.preventDefault();nodes[0]?.focus();}}});$('modalRoot').addEventListener('click',ev=>{if(ev.target===$('modalRoot'))closeModal();});
let gridTab='loads',gridDetails=0,gridSelection=new Set();
const G=window.VoltGrid;
function syncTechnical(){if(state.mode!=='technical'||!state.editingId)return;const i=state.circuits.findIndex(c=>c.id===state.editingId);if(i>=0)state.circuits[i]=structuredClone(state.draft);}
function enterTechnical(){
 if(state.editingId){const i=state.circuits.findIndex(c=>c.id===state.editingId);if(i>=0)state.circuits[i]=structuredClone(state.draft);}
 else if(state.draft.description||!state.circuits.length||JSON.stringify({...state.draft,id:'',loads:state.draft.loads.map(l=>({...l,id:''}))})!==JSON.stringify({...M.newCircuit(),id:'',loads:[{...M.newLoad(),id:''}]})){
  if(state.circuits.length>=300)return toast('Limite de 300 circuitos. Salve o rascunho em outro projeto.');
  state.circuits.push(structuredClone(state.draft));state.editingId=state.draft.id;
 }else{state.draft=structuredClone(state.circuits[0]);state.editingId=state.draft.id;}
 state.mode='technical';state.page='wizard';persist();render();
}
function gridCell(c,column,row,j){
 const value=(column.load?c.loads[0]:c)?.[column.key]??'';
 if(column.load&&c.loads.length!==1)return `<td><button class="grid-groups" data-grid-open="${row}" data-grid-detail="2">${c.loads.length} grupos</button></td>`;
 const attrs=`data-grid-row="${row}" data-grid-col="${j}" aria-describedby="grid-diagnostic-${row}-${j}" aria-label="Linha ${row+1}: ${esc(column.label)}"`;
 const input=column.options?`<select ${attrs}>${G.options(column).some(([v])=>v===value)?'':'<option value="">Pendente</option>'}${G.options(column).map(([v,label])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input ${attrs} value="${esc(value)}" ${['number','description'].includes(column.key)?'maxlength="70"':'inputmode="decimal"'}>`;
 return `<td>${input}<span id="grid-diagnostic-${row}-${j}" class="grid-cell-error" data-grid-error="${row}-${j}"></span></td>`;
}
function gridResult(c){const r=calc(c),pending=(r.diagnostics||[]).filter(d=>d.field!=='shortIk');return `<strong>${fmt(r.ib)} A · ${fmt(r.voltage)} V</strong><small>${r.chosen?'Cabo '+fmt(r.chosen.section)+' mm² · disj. '+fmt(r.protection.nominal)+' A':'Seleção pendente'}</small><small>${r.pending?'Calculando…':pending.length?pending.length+' pendência(s)':r.shortOk===null?'Interrupção pendente':'Verificações parciais'}</small>`;}
function technicalView(){return `<section class="panel card-section grid-panel"><div class="card-title"><div><span class="eyebrow">Modo técnico</span><h2>Planilha de circuitos</h2><p>Edição salva neste navegador. Resultados recalculados pelo Python.</p></div><div class="head-actions"><button class="btn secondary small" data-action="export">Backup JSON</button><button class="btn secondary small" data-page="loads">Quadro de cargas</button><button class="btn primary small" data-grid-action="add">+ Circuito</button></div></div>${supplyView()}<div class="grid-toolbar"><div class="grid-tabs">${[['loads','Cargas'],['installation','Instalação'],['conditions','Condições e proteção']].map(([key,label])=>`<button class="btn small ${gridTab===key?'primary':'secondary'}" data-grid-tab="${key}" aria-pressed="${gridTab===key}">${label}</button>`).join('')}</div><div class="grid-tabs"><button class="btn secondary small" data-grid-action="duplicate">Duplicar selecionados</button><button class="btn secondary small" data-grid-action="bulk">Aplicar condições…</button></div></div><p class="hint">Role a tabela para ver todas as colunas. Cole células do Excel a partir de uma célula (sem cabeçalho, números sem separador de milhar). Tab avança; Enter desce. A aba Cargas edita o grupo único; vários grupos ficam em Detalhes. In informado só é usado em Verificar.</p><div class="table-wrap grid-scroll"><table class="circuit-grid"><caption class="sr-only">Circuitos editáveis — ${state.circuits.length} linhas</caption><thead><tr><th><input type="checkbox" data-grid-all aria-label="Selecionar todos os circuitos" ${state.circuits.length&&state.circuits.every(c=>gridSelection.has(c.id))?'checked':''}></th><th>Editar</th>${G.columns[gridTab].map(c=>`<th>${esc(c.label)}</th>`).join('')}<th>Pré-dimensionamento</th></tr></thead><tbody>${state.circuits.map((c,i)=>`<tr class="${state.editingId===c.id?'grid-active':''}"><td><input type="checkbox" data-grid-select="${esc(c.id)}" aria-label="Selecionar circuito ${i+1}" ${gridSelection.has(c.id)?'checked':''}></td><td><button class="btn secondary small" data-grid-open="${i}" data-grid-detail="2">Detalhes</button><button class="btn ghost small" data-grid-open="${i}" data-grid-detail="6">Resultado</button></td>${G.columns[gridTab].map((column,j)=>gridCell(c,column,i,j)).join('')}<td class="grid-result" data-grid-result="${i}">${gridResult(c)}</td></tr>`).join('')}</tbody></table></div><p class="hint">As condições iniciais são hipóteses editáveis. Corrija as células destacadas; instalações fora das tabelas permanecem pendentes.</p></section>${gridDetails?`<section class="panel card-section grid-detail"><div class="card-title"><h2>${esc(state.draft.number||'Circuito')} · ${esc(state.draft.description||'Sem nome')}</h2><button class="btn secondary small" data-grid-detail="0">Fechar detalhes</button></div><div class="grid-tabs">${LABELS.map((label,i)=>`<button class="btn small ${gridDetails===i+1?'primary':'secondary'}" data-grid-detail="${i+1}">${label}</button>`).join('')}</div><div class="grid-detail-body">${[circuitView,()=>connectionView()+equipmentView()+routeView(),installationView,groupingView,conditionsView,resultView][gridDetails-1]()}</div></section>`:''}`;}
function paintDiagnostics(){
 const r=calc(state.draft),diagnostics=r.diagnostics||[];
 document.querySelectorAll('.field-diagnostic').forEach(el=>el.remove());
 document.querySelectorAll('[aria-invalid="true"]').forEach(el=>el.removeAttribute('aria-invalid'));
 for(const el of document.querySelectorAll('[data-field],[data-load]')){
  const scope=el.dataset.load?'load':'field',key=el.dataset.load||el.dataset.field;
  const entries=diagnostics.filter(d=>!(d.blocksSelection&&!d.blocking)&&d.scope===scope&&(d.field===key||(key==='voltageMode'&&d.field==='voltage'))&&(scope!=='load'||d.index===+el.dataset.index));
  if(entries.length){el.setAttribute('aria-invalid','true');const msg=document.createElement('small');msg.className='field-diagnostic';msg.id=el.id+'-diagnostic';msg.textContent=[...new Set(entries.map(d=>d.message))].join(' ');el.setAttribute('aria-describedby',msg.id);el.after(msg);}else if(el.getAttribute('aria-describedby')?.endsWith('-diagnostic'))el.removeAttribute('aria-describedby');
 }
 document.querySelectorAll('[data-diagnostics]').forEach(el=>el.innerHTML=diagnostics.length?`<details class="details" ${diagnostics.some(d=>d.blocksSelection)?'open':''}><summary>${diagnostics.length} pendência(s) ou verificações · ${state.draft.description?esc(state.draft.description):'circuito atual'}</summary><ul class="diagnostic-list">${diagnostics.map((d,i)=>`<li><button data-diagnostic="${i}">${LABELS[d.step-1]} — ${esc(d.message)}</button></li>`).join('')}</ul></details>`:'');
 if(state.mode!=='technical')return;
 state.circuits.forEach((c,i)=>{
  const result=calc(c),el=document.querySelector(`[data-grid-result="${i}"]`);if(el)el.innerHTML=gridResult(c);
  G.columns[gridTab].forEach((column,j)=>{const cell=document.querySelector(`[data-grid-row="${i}"][data-grid-col="${j}"]`),msg=document.querySelector(`[data-grid-error="${i}-${j}"]`);if(!cell||!msg)return;if(cell!==document.activeElement)cell.value=(column.load?c.loads[0]:c)?.[column.key]??'';cell.closest('tr').classList.toggle('grid-active',state.editingId===c.id);const entries=(result.diagnostics||[]).filter(d=>d.field===column.key&&d.scope===(column.load?'load':'field')&&(!column.load||d.index===0));msg.textContent=entries.length?'Confira o campo':'';cell.title=entries.map(d=>d.message).join(' ');if(entries.length)cell.setAttribute('aria-invalid','true');});
 });
}
let gridRefresh=0;
async function refreshGrid(){const version=++gridRefresh;await prepare(state.circuits);if(version===gridRefresh)paintDiagnostics();}
function selectGridRow(row){syncTechnical();const c=state.circuits[row];if(!c)return;state.draft=structuredClone(c);state.editingId=c.id;state.selected=c.id;}
function gridInput(target){const row=+target.dataset.gridRow,col=+target.dataset.gridCol,c=state.circuits[row];try{const next=structuredClone(c);G.set(next,G.columns[gridTab][col],target.value,false);syncTechnical();if(state.editingId!==next.id&&gridDetails){gridDetails=0;document.querySelector('.grid-detail')?.remove();}state.circuits[row]=next;state.draft=structuredClone(next);state.editingId=next.id;state.selected=next.id;persist();target.setCustomValidity('');if(G.columns[gridTab][col].key==='connection'){const phase=document.querySelector(`[data-grid-row="${row}"][data-grid-col="3"]`);if(phase)phase.value=next.phaseSet;}refreshGrid();}catch(error){target.setCustomValidity(error.message);toast(error.message);}}
function gridBulk(){const selected=state.circuits.filter(c=>gridSelection.has(c.id));if(!selected.length)return toast('Selecione os circuitos que receberão as condições.');const keys=['installation','cableForm','wall','metal','insulation','temperature','groupCount','groupLayout','maxDrop'];const labels={installation:'Instalação e método',cableForm:'Construção do cabo',wall:'Parede',metal:'Metal',insulation:'Isolação',temperature:'Temperatura',groupCount:'Quantidade agrupada',groupLayout:'Disposição do agrupamento',maxDrop:'Limite de queda'};modal('Aplicar condições aos selecionados',`<p>Origem: <strong>${esc(state.draft.description||'Circuito atual')}</strong>. Destino: ${selected.length} circuito(s). Marque apenas os campos que deseja substituir.</p>${keys.map(key=>`<label class="radio-row"><input type="checkbox" data-bulk-key="${key}">${labels[key]}: ${esc(G.options(Object.values(G.columns).flat().find(c=>c.key===key)||{}).find(([v])=>v===state.draft[key])?.[1]||state.draft[key]||'Pendente')}</label>`).join('')}`,'<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" data-grid-action="applyBulk">Aplicar campos marcados</button>');}
async function gridClick(d){
 if(d.gridTab){gridTab=d.gridTab;await render();return;}
 if(d.gridOpen!==undefined)selectGridRow(+d.gridOpen);
 if(d.gridDetail!==undefined){gridDetails=+d.gridDetail;persist();await render();document.querySelector('.grid-detail')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(d.diagnostic!==undefined){const entry=calc(state.draft).diagnostics?.[+d.diagnostic];if(!entry)return;state.page='wizard';if(state.mode==='technical')gridDetails=entry.step;else state.step=entry.step;await render();const selector=entry.scope==='load'?`[data-load="${entry.field}"][data-index="${entry.index}"]`:`[data-field="${entry.field}"]`;const input=document.querySelector(selector);input?.closest('details')?.setAttribute('open','');input?.focus();return;}
 switch(d.gridAction){
 case 'add':if(state.circuits.length>=300)return toast('Limite de 300 circuitos.');syncTechnical();state.draft=M.newCircuit();state.editingId=state.draft.id;state.circuits.push(structuredClone(state.draft));persist();await render();document.querySelector(`[data-grid-row="${state.circuits.length-1}"][data-grid-col="1"]`)?.focus();break;
 case 'duplicate':{const selected=state.circuits.filter(c=>gridSelection.has(c.id));if(!selected.length)return toast('Selecione os circuitos para duplicar.');if(state.circuits.length+selected.length>300)return toast('A duplicação ultrapassa 300 circuitos.');selected.forEach(c=>{const copy=structuredClone(c);copy.id=M.id();copy.number='';copy.description=(copy.description+' — cópia').slice(0,70);state.circuits.push(copy);});persist();render();break;}
 case 'bulk':gridBulk();break;
 case 'applyBulk':{const keys=[...document.querySelectorAll('[data-bulk-key]:checked')].map(el=>el.dataset.bulkKey);if(!keys.length)return toast('Marque ao menos um campo.');const source=structuredClone(state.draft);for(const c of state.circuits.filter(c=>gridSelection.has(c.id))){keys.forEach(key=>c[key]=source[key]);if(keys.includes('installation')){c.methodOverride=source.methodOverride;c.unknownInstallation=source.unknownInstallation;}}state.draft=structuredClone(state.circuits.find(c=>c.id===state.editingId)||state.draft);persist();closeModal();render();break;}
 }
}
document.addEventListener('paste',async ev=>{const target=ev.target;if(target.dataset.gridRow===undefined)return;ev.preventDefault();try{syncTechnical();const next=G.paste(state.circuits,gridTab,+target.dataset.gridRow,+target.dataset.gridCol,ev.clipboardData.getData('text/plain'));state.circuits=next;state.draft=structuredClone(next[+target.dataset.gridRow]);state.editingId=state.draft.id;persist();await render();toast('Células coladas. Confira as pendências e os resultados.');}catch(error){toast('Colagem não aplicada: '+error.message);}});
document.addEventListener('keydown',async ev=>{if(ev.key!=='Enter'||ev.target.dataset.gridRow===undefined)return;ev.preventDefault();const row=+ev.target.dataset.gridRow,col=ev.target.dataset.gridCol;const next=[...document.querySelectorAll(`[data-grid-col="${col}"]`)].find(el=>+el.dataset.gridRow>row);next?.focus();});

document.addEventListener('focusin',ev=>{const row=ev.target.dataset.gridRow;if(row===undefined||state.circuits[+row]?.id===state.editingId)return;selectGridRow(+row);if(gridDetails){gridDetails=0;document.querySelector('.grid-detail')?.remove();}persist();paintDiagnostics();});
load();render();
})();
